const b = $input.first().json.body || $input.first().json;

function s(v) { return (v === undefined || v === null) ? '' : String(v).trim(); }

const name = s(b.name);
const phone = s(b.phone);
const email = s(b.email).toLowerCase();
const course_interest = s(b.course_interest);
const message = s(b.message);

const request_id = `CI-${Date.now()}-${$execution.id}`;
const received_at = new Date().toISOString();

return [{
  json: {
    request_id,
    received_at,
    name,
    phone,
    email,
    course_interest,
    message,
    raw_input: b
  }
}];

const item = $input.first().json;

const normalized_phone = (item.phone || '').replace(/[^0-9]/g, '');
const normalized_message = (item.message || '').trim().toLowerCase();

return [{
  json: {
    ...item,
    normalized_phone,
    normalized_message
  }
}];

const original = $('04a2_Hash_Fingerprint').first().json;
const matches = $input.all().map(i => i.json);

const windowHours = original.duplicate_window_hours || 24;
const now = new Date(original.received_at);

let is_duplicate = false;

for (const m of matches) {
  // Must have both duplicate_key and timestamp
  if (!m.duplicate_key || !m.timestamp) continue;

  // Must have the same duplicate_key
  if (m.duplicate_key !== original.duplicate_key) continue;

  const t = new Date(m.timestamp);

  // Absolute time difference in hours
  const diffHours = Math.abs(now - t) / (1000 * 60 * 60);

  if (diffHours <= windowHours) {
    is_duplicate = true;
    break;
  }
}

return [{
  json: {
    ...original,
    is_duplicate
  }
}];

const input = $input.first().json;

const phone = input.phone || "";
const email = input.email || "";

// Mask phone: keep first 3 and last 4 digits
const phone_masked = phone.length >= 7
  ? `${phone.slice(0, 3)}****${phone.slice(-4)}`
  : "****";

// Mask email: keep first character + domain
let email_masked = "";
if (email.includes("@")) {
  const [localPart, domain] = email.split("@");
  email_masked = `${localPart.charAt(0)}***@${domain}`;
} else {
  email_masked = "***";
}

return [{
  json: {
    ...input,
    phone_masked,
    email_masked
  }
}];

const item = $input.first().json;
const maxLen = item.max_ai_message_length || 1500;
const original_message_length = item.message.length;
let ai_message = item.message;
let message_truncated = false;

if (original_message_length > maxLen) {
  ai_message = item.message.slice(0, maxLen);
  message_truncated = true;
}

return [{
  json: {
    ...item,
    ai_message,
    original_message_length,
    message_truncated
  }
}];

const item = $input.first().json;

const ai_user_content = JSON.stringify({
  course_interest: item.course_interest,
  message: item.ai_message
});

return [{
  json: {
    ...item,
    ai_user_content
  }
}];

