const item = $input.first().json;
const resp = item;

let ai_parse_success = false;
let ai_raw_json = null;
let ai_parse_error = '';

const ai_input_tokens =
  (resp.usage && resp.usage.prompt_tokens) || 0;

const ai_output_tokens =
  (resp.usage && resp.usage.completion_tokens) || 0;

try {
  // Groq / OpenAI-compatible response
  const text =
    resp.choices &&
    resp.choices[0] &&
    resp.choices[0].message &&
    resp.choices[0].message.content;

  if (!text) {
    throw new Error('AI response content is empty or missing');
  }

  ai_raw_json = JSON.parse(text);
  ai_parse_success = true;

} catch (e) {
  ai_parse_error = e.message;
}

// ai_parse_success = false;    //for test purpose
// ai_parse_error = 'Testing Retry';   //for test purpose

return [
  {
    json: {
      ...$('05_Prepare_AI_Input').first().json,
      ai_parse_success,
      ai_raw_json,
      ai_parse_error,
      ai_input_tokens,
      ai_output_tokens
    }
  }
];

const item = $input.first().json;
const errors = [];

const allowedIntent = [
  'price',
  'schedule',
  'job_placement',
  'complaint',
  'spam',
  'other'
];

const allowedLang = [
  'bn',
  'en',
  'mixed'
];

const requiredFields = [
  'intent',
  'lead_score',
  'language',
  'summary',
  'suggested_reply',
  'needs_human'
];

let out = {
  intent: null,
  lead_score: null,
  language: null,
  summary: null,
  suggested_reply: null,
  needs_human: null
};

// --------------------------------------------------
// 1. Check whether AI JSON parsing succeeded
// --------------------------------------------------

if (!item.ai_parse_success || !item.ai_raw_json) {

  errors.push(
    'AI response was not valid JSON: ' +
    (item.ai_parse_error || 'unknown parsing error')
  );

} else {

  const j = item.ai_raw_json;

  // ------------------------------------------------
  // 2. Validate required fields
  // ------------------------------------------------

  for (const field of requiredFields) {
    if (!Object.prototype.hasOwnProperty.call(j, field)) {
      errors.push('missing required field: ' + field);
    }
  }

  // ------------------------------------------------
  // 3. Validate intent
  // ------------------------------------------------

  if (allowedIntent.includes(j.intent)) {
    out.intent = j.intent;
  } else {
    errors.push('invalid intent: ' + j.intent);
  }

  // ------------------------------------------------
  // 4. Validate lead score
  // ------------------------------------------------

  const score = Number(j.lead_score);

  if (
    Number.isInteger(score) &&
    score >= 1 &&
    score <= 10
  ) {
    out.lead_score = score;
  } else {
    errors.push(
      'invalid lead_score: ' + j.lead_score
    );
  }

  // ------------------------------------------------
  // 5. Validate language
  // ------------------------------------------------

  if (allowedLang.includes(j.language)) {
    out.language = j.language;
  } else {
    errors.push(
      'invalid language: ' + j.language
    );
  }

  // ------------------------------------------------
  // 6. Validate summary
  // ------------------------------------------------

  if (
    typeof j.summary === 'string' &&
    j.summary.trim().length > 0
  ) {
    out.summary = j.summary.trim();
  } else {
    errors.push('invalid summary');
  }

  // ------------------------------------------------
  // 7. Validate suggested reply
  // ------------------------------------------------

  const reply =
    typeof j.suggested_reply === 'string'
      ? j.suggested_reply.trim()
      : '';

  const wordCount = reply
    .split(/\s+/)
    .filter(Boolean)
    .length;

  const maxWords = Number(item.max_reply_words) || 80;

  if (!reply) {

    errors.push(
      'invalid suggested_reply: empty'
    );

  } else if (wordCount > maxWords) {

    errors.push(
      'invalid suggested_reply: ' +
      wordCount +
      ' words exceeds maximum ' +
      maxWords
    );

  } else {

    out.suggested_reply = reply;
  }

  // ------------------------------------------------
  // 8. Validate needs_human
  // ------------------------------------------------

  if (typeof j.needs_human === 'boolean') {
    out.needs_human = j.needs_human;
  } else {
    errors.push(
      'invalid needs_human: ' + j.needs_human
    );
  }
}

// --------------------------------------------------
// 9. Final validation result
// --------------------------------------------------

const ai_valid = errors.length === 0;

return [
  {
    json: {
      ...item,
      ...out,
      ai_valid,
      ai_validation_errors: errors
    }
  }
];

