const item = $input.first().json;

let route_taken = 'low';
if (item.intent === 'spam') route_taken = 'spam';
else if (item.lead_score >= item.hot_threshold) route_taken = 'hot';
else if (item.lead_score >= item.medium_threshold) route_taken = 'medium';

const inputPrice = item.claude_input_price_per_m || 0;
const outputPrice = item.claude_output_price_per_m || 0;
const estimated_input_tokens = item.ai_input_tokens || 0;
const estimated_output_tokens = item.ai_output_tokens || 0;
const estimated_token_cost = (estimated_input_tokens / 1000000 * inputPrice) + (estimated_output_tokens / 1000000 * outputPrice);

return [{
  json: {
    ...item,
    route_taken,
    estimated_input_tokens,
    estimated_output_tokens,
    estimated_token_cost
  }
}];

const item = $input.first().json;

const error = item.error || {};

const errorMessage =
  error.message ||
  error.description ||
  'Unknown AI API error';

const lowerMessage = errorMessage.toLowerCase();

const isAuthError =
  lowerMessage.includes('authorization failed') ||
  lowerMessage.includes('unauthorized') ||
  lowerMessage.includes('invalid api key') ||
  lowerMessage.includes('authentication') ||
  lowerMessage.includes('credentials') ||
  lowerMessage.includes('401');

return [
  {
    json: {
      ...$('05_Prepare_AI_Input').first().json,

      ai_api_failed: true,
      ai_error_message: errorMessage,

      ai_error_type: isAuthError
        ? 'credential_error'
        : 'api_error',

      ai_auth_error: isAuthError
    }
  }
];

const item = $input.first().json;

// n8n error output can expose the error in different shapes.
const error = item.error || {};

const errorMessage =
  error.message ||
  error.description ||
  item.message ||
  'Unknown AI retry error';

const errorName =
  error.name ||
  'AI_RETRY_ERROR';

// Preserve the original lead data from the node
// that entered the retry path.
let original = {};

try {
  original = $('IF_AI_Valid').first().json;
} catch (e) {
  original = {};
}

return [
  {
    json: {
      ...original,

      // Retry failure information
      ai_api_failed: true,
      ai_retry_failed: true,
      ai_fallback_used: true,

      ai_error_type: 'retry_api_error',
      ai_error_name: errorName,
      ai_error_message: errorMessage,

      // Final deterministic fallback classification
      intent: 'other',
      lead_score: 5,
      language: 'mixed',

      summary:
        'AI classification failed after the retry attempt and requires human review.',

      suggested_reply:
        original.fallback_suggested_reply ||
        'আন্তরিকভাবে দুঃখিত, আমাদের সিস্টেমে সাময়িক সমস্যা হয়েছে। আমাদের একজন প্রতিনিধি শীঘ্রই সরাসরি যোগাযোগ করবেন।',

      needs_human: true,

      // AI result is not valid because both attempts failed
      ai_valid: false,

      ai_validation_errors: [
        'Initial AI request failed or produced an invalid result.',
        'Retry AI request failed: ' + errorMessage
      ]
    }
  }
];
